import{_ as o,C as s,o as n,c as r,j as t,a as i,E as l,a6 as h}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse('{"title":"Watch all workers","description":"See every worker of a running Playwright run at once on its run page, an image a second each, and let the live view follow the worker whose test failed, got stuck or stopped, saying why.","frontmatter":{"title":"Watch all workers","description":"See every worker of a running Playwright run at once on its run page, an image a second each, and let the live view follow the worker whose test failed, got stuck or stopped, saying why.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/watch-all.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/watch-all.html"}],["meta",{"property":"og:title","content":"Watch all workers | Piwi for Playwright"}],["meta",{"property":"og:description","content":"See every worker of a running Playwright run at once on its run page, an image a second each, and let the live view follow the worker whose test failed, got stuck or stopped, saying why."}]]},"headers":[],"relativePath":"features/watch-all.md","filePath":"features/watch-all.md","lastUpdated":1794644822000}'),d={name:"features/watch-all.md"};function w(c,e,u,p,g,f){const a=s("Needs");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"watch-all-workers",tabindex:"-1"},[i("Watch all workers "),t("a",{class:"header-anchor",href:"#watch-all-workers","aria-label":'Permalink to "Watch all workers"'},"​")],-1)),l(a,{reporter:"",fixtures:""}),e[1]||(e[1]=h('<p><strong>Watch all</strong>, on a running run&#39;s <strong>Tests</strong> tab, shows a tile for each worker in the run&#39;s <a href="./live-view.html">live view</a>: the page its test is on, one image a second, with the worker&#39;s number, its test and the step it is on. A click on a tile shows that worker in full, in the panel <strong>Watch</strong> opens. It is for a run of many workers where you do not know yet which one to look at. It needs what the live view needs: the project&#39;s live view on, and a CI run or a run <a href="./share-live.html">shared from a developer&#39;s machine</a>.</p><h2 id="what-a-tile-shows" tabindex="-1">What a tile shows <a class="header-anchor" href="#what-a-tile-shows" aria-label="Permalink to &quot;What a tile shows&quot;">​</a></h2><ul><li><strong>The page</strong>, as the worker&#39;s test sees it: one image a second, 320 pixels wide, the latest alone. A still page sends none until it changes.</li><li><strong>The worker</strong>, by its lane (<code>Worker 2</code>, as the rows and the Timeline name it), the test it runs and its step.</li><li><strong>What its test needs attention for</strong>: where it stands stopped (<code>Stopped at a breakpoint</code>), or <strong>Stuck?</strong> once the dashboard marks it (<a href="./stuck-tests.html">Stuck tests</a>).</li></ul><p>The tile of the worker shown in full is outlined. A worker that leaves the run&#39;s live view leaves the grid; the one Playwright starts in its lane after a failure takes its place.</p><h2 id="follow-what-needs-attention" tabindex="-1">Follow what needs attention <a class="header-anchor" href="#follow-what-needs-attention" aria-label="Permalink to &quot;Follow what needs attention&quot;">​</a></h2><p>In the full view, <strong>Follow what needs attention</strong> moves the view on its own to a worker whose test failed, was marked <strong>Stuck?</strong>, or stopped (a breakpoint, a <code>page.pause()</code> or <strong>Pause</strong>), and says why it moved: <code>Moved to worker 3: “pays with a saved card” failed.</code> It follows these rules:</p><ul><li>It goes where the newest of them happened, in another worker of the run&#39;s live view.</li><li>It stays at least 5 seconds after it moved or you chose a worker yourself (a tile, a row&#39;s <strong>Watch</strong>).</li><li>It stays on a worker that needs attention itself: one stopped or marked <strong>Stuck?</strong>, for as long as it lasts, and one whose test failed, for 10 seconds.</li><li>A failure from before you turned it on, or that the run page saw more than 30 seconds ago, the view open or closed, moves nothing; nor does anything from before you last chose a worker yourself.</li></ul><p>After a failure, Playwright starts a new worker in the lane: the view shows its next test, and the line under its checkboxes says which test failed. The view moves within its panel, which stays in full screen if you put it there.</p><h2 id="one-connection" tabindex="-1">One connection <a class="header-anchor" href="#one-connection" aria-label="Permalink to &quot;One connection&quot;">​</a></h2><p>The run page holds one connection to the dashboard for everything it watches: the tiles and the full view travel together, and showing another worker or resizing the panel changes what it carries without opening another. The full view&#39;s images come at the size the panel shows them, up to 1280 by 800 pixels; a worker shown in full and as a tile sends the larger. Each worker sends images only while a page shows it, in full or as a tile, and nothing is stored: <a href="./live-view.html#what-is-sent-to-whom-and-what-is-kept">what is sent, to whom, and what is kept</a> applies to every tile.</p><p>A run takes 16 such pages at a time, whatever each shows, and its workers send 4 MB of images a second at most together. Each page gets 1 MB of images a second at most, the latest of each worker waiting for the next second, and a page that reads nothing for 5 seconds is cut off, then connects again. A tile carries no call log, nor the <a href="./live-view-layers.html">events, text or filmstrip</a> of the full view, and an image of 48 KB at most: a worker someone else watches in full at a large size says so in its tile. In a tab hidden for 10 minutes, the page stops asking for tiles, and asks again as you come back. An older reporter sends its images at 640 by 400 pixels, four a second, whatever the view asks; the dashboard passes one a second of them to a tile.</p><h2 id="in-the-demo" tabindex="-1">In the demo <a class="header-anchor" href="#in-the-demo" aria-label="Permalink to &quot;In the demo&quot;">​</a></h2><p>The live demo runs no browser: <strong>Watch all</strong> on a simulated run shows each running worker&#39;s step where its image would be, and its stops and <strong>Stuck?</strong> marks. A tile opens no full view there, so no page events, text, filmstrip or Inspect.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live-view.html">Live view of a run</a>: turning it on, and the full view of one worker</li><li><a href="./stuck-tests.html">Stuck tests</a>: when a test is marked <strong>Stuck?</strong></li><li><a href="./share-live.html">Share a run live</a>: let a teammate watch a run on your machine</li><li><a href="./watch-a-run.html">Watch a run</a>: where a run is followed, on every tool</li></ul>',15))])}const v=o(d,[["render",w]]);export{k as __pageData,v as default};
